--
-- Table structure for table `empresas`
--

DROP TABLE IF EXISTS `empresas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `empresas` (
  `empresa_id` int NOT NULL AUTO_INCREMENT,
  `ruc` varchar(11) NOT NULL,
  `razon_social` varchar(255) NOT NULL,
  `nombre_comercial` varchar(255) DEFAULT NULL,
  `direccion` varchar(255) DEFAULT NULL,
  `certificado_digital` longblob,
  `clave_certificado` varchar(100) DEFAULT NULL,
  `usuario_sol_secundario` varchar(50) NOT NULL,
  `clave_sol_secundario` varchar(100) NOT NULL,
  `modo` varchar(10) DEFAULT 'BETA',
  `estado` tinyint DEFAULT '1',
  `logo` varchar(255) DEFAULT NULL,
  `email` varchar(45) DEFAULT NULL,
  `telefono` varchar(20) DEFAULT NULL,
  `logo_public_id` varchar(100) DEFAULT NULL,
  `create_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `certificado_nombre` varchar(255) DEFAULT NULL,
  `certificado_hash` varchar(128) DEFAULT NULL,
  `certificado_subject` varchar(255) DEFAULT NULL,
  `certificado_issuer` varchar(255) DEFAULT NULL,
  `certificado_valido_desde` date DEFAULT NULL,
  `certificado_valido_hasta` date DEFAULT NULL,
  `certificado_public_id` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`empresa_id`),
  UNIQUE KEY `ruc` (`ruc`)
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
